16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be E.164 form: a leading '+' followed by 8 to 15 digits")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date", columnDefinition = "DATE")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "birth_date", columnDefinition = "DATE")
60	    private LocalDate birthDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "household_id")
66	    private String householdId;
67	
68	    @Column(name = "namesake_count")
69	    private Integer namesakeCount;
70	
71	    @Column(name = "household_size")
72	    private Integer householdSize;
73	
74	    @Column(name = "postcode")
75	    private String postcode;
76	
77	    @Column(name = "possible_duplicate")
78	    private Boolean possibleDuplicate;
79	
80	    @Column(name = "possible_duplicate_of")
81	    private Integer possibleDuplicateOf;
82	
83	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
84	    private Set<Pet> pets;
85	
86	    public String getAddress() {
87	        return this.address;
88	    }
89	
90	    public void setAddress(String address) {
91	        this.address = address;
92	    }
93	
94	    public String getCity() {
95	        return this.city;
96	    }
97	
98	    public void setCity(String city) {
99	        this.city = city;
100	    }
101	
102	    public String getTelephone() {
103	        return this.telephone;
104	    }
105	
106	    public void setTelephone(String telephone) {
107	        this.telephone = telephone;
108	    }
109	
110	    public String getEmail() {
111	        return this.email;
112	    }
113	
114	    /**
115	     * Stores the email lower-cased so it is persisted and returned in a canonical form. A
116	     * {@code null} value (email omitted) is preserved as {@code null}.
117	     */
118	    public void setEmail(String email) {
119	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
120	    }
121	
122	    public LocalDate getRegistrationDate() {
123	        return this.registrationDate;
124	    }
125	
126	    public void setRegistrationDate(LocalDate registrationDate) {
127	        this.registrationDate = registrationDate;
128	    }
129	
130	    public LocalDate getBirthDate() {
131	        return this.birthDate;
132	    }
133	
134	    public void setBirthDate(LocalDate birthDate) {
135	        this.birthDate = birthDate;
136	    }
137	
138	    /**
139	     * The owner's age band, derived from {@link #birthDate} measured against the
140	     * {@link #registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64
141	     * inclusive, and {@code SENIOR} at 65 or over. Returns {@code null} when no birth date was
142	     * supplied, so the field is simply absent from the response.
143	     */
144	    @Transient
145	    public String getAgeBand() {
146	        if (this.birthDate == null) {
147	            return null;
148	        }
149	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
150	        int age = java.time.Period.between(this.birthDate, reference).getYears();
151	        if (age < 18) {
152	            return "MINOR";
153	        }
154	        if (age < 65) {
155	            return "ADULT";
156	        }
157	        return "SENIOR";
158	    }
159	
160	    /** National-number length by country code, mirroring the create-time E.164 normalization. */
161	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
162	
163	    /**
164	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
165	     * national digits grouped in threes from the left (e.g. {@code +61412345678 -> +61 412 345 678}).
166	     * The country code is recognised from the known set ({@code +61} with 9 national digits, {@code +1}
167	     * with 10) that the create-time normalization produces. Values that are absent or not in E.164 form
168	     * are returned unchanged, so the raw {@link #telephone} still stands in for a display value.
169	     */
170	    @Transient
171	    public String getTelephoneDisplay() {
172	        if (this.telephone == null || !this.telephone.startsWith("+")) {
173	            return this.telephone;
174	        }
175	        String digits = this.telephone.substring(1);
176	        if (!digits.matches("[0-9]+")) {
177	            return this.telephone;
178	        }
179	        String countryCode = null;
180	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
181	            if (digits.startsWith(entry.getKey())
182	                && digits.length() - entry.getKey().length() == entry.getValue()) {
183	                countryCode = entry.getKey();
184	                break;
185	            }
186	        }
187	        if (countryCode == null) {
188	            return this.telephone;
189	        }
190	        String national = digits.substring(countryCode.length());
191	        StringBuilder grouped = new StringBuilder();
192	        for (int i = 0; i < national.length(); i += 3) {
193	            if (grouped.length() > 0) {
194	                grouped.append(' ');
195	            }
196	            grouped.append(national, i, Math.min(i + 3, national.length()));
197	        }
198	        return "+" + countryCode + " " + grouped;
199	    }
200	
201	    public String getCustomerCode() {
202	        return this.customerCode;
203	    }
204	
205	    public void setCustomerCode(String customerCode) {
206	        this.customerCode = customerCode;
207	    }
208	
209	    /**
210	     * A single Luhn check digit (0-9) computed over the digits contained in the
211	     * {@link #customerCode}. Non-digit characters in the code are ignored; the standard Luhn
212	     * algorithm doubles every second digit from the right (subtracting 9 when the result exceeds
213	     * 9) and the check digit is {@code (10 - (sum % 10)) % 10}. {@code null} until a customer code
214	     * is assigned.
215	     */
216	    @Transient
217	    public Integer getCheckDigit() {
218	        if (this.customerCode == null) {
219	            return null;
220	        }
221	        int sum = 0;
222	        boolean dbl = true;
223	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
224	            char c = this.customerCode.charAt(i);
225	            if (c < '0' || c > '9') {
226	                continue;
227	            }
228	            int d = c - '0';
229	            if (dbl) {
230	                d *= 2;
231	                if (d > 9) {
232	                    d -= 9;
233	                }
234	            }
235	            sum += d;
236	            dbl = !dbl;
237	        }
238	        return (10 - (sum % 10)) % 10;
239	    }
240	
241	    /**
242	     * The owner's membership number, formatted {@code <customerCode>-M<YY>} where {@code YY} is
243	     * the last two digits of the {@code registrationDate} year (e.g. {@code NSW-1A2B3C4D-M26}).
244	     * Derived from the owner's own fields; {@code null} until both are assigned.
245	     */
246	    @Transient
247	    public String getMembershipNumber() {
248	        if (this.customerCode == null || this.registrationDate == null) {
249	            return null;
250	        }
251	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
252	    }
253	
254	    /**
255	     * The owner's membership level, a number from 1 to 3 derived from the owner's own fields as
256	     * captured at creation time. It starts at 1, gains 1 when an email is present, gains a further
257	     * 1 when the owner has no namesakes ({@code namesakeCount} is 0), and is capped at 3. Level 4
258	     * is reserved for tenure and is never produced here.
259	     */
260	    @Transient
261	    public Integer getMembershipLevel() {
262	        int level = 1;
263	        boolean hasEmail = this.email != null && !this.email.isBlank();
264	        if (hasEmail) {
265	            level++;
266	        }
267	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
268	        if (noNamesakes) {
269	            level++;
270	        }
271	        return Math.min(level, 3);
272	    }
273	
274	    /** City -> canonical region for the {@code region} derivation. */
275	    private static final Map<String, String> CITY_REGION = Map.of(
276	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
277	
278	    /** Region -> inclusive 4-digit postcode range {low, high} for the {@code region} derivation. */
279	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
280	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
281	
282	    /**
283	     * The region code that forms the {@code REGION} segment of the {@link #customerCode}, derived
284	     * by looking up the region by {@link #postcode} range first (NSW 2000-2099, VIC 3000-3099,
285	     * QLD 4000-4099), and only falling back to the fixed city-to-region table (Sydney->NSW,
286	     * Melbourne->VIC, Brisbane->QLD) when the postcode is absent or in no known range. Returns
287	     * {@code UNKNOWN} when neither source resolves a region.
288	     */
289	    @Transient
290	    public String getRegion() {
291	        String region = regionForPostcode(this.postcode);
292	        if (region != null) {
293	            return region;
294	        }
295	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
296	    }
297	
298	    /**
299	     * The owner's locality: the {@code REGION} segment of its {@link #customerCode} (everything
300	     * before the first {@code '-'}). Because the customer code is {@code <REGION>-<HASH8>} with
301	     * {@code REGION} derived from the postcode, the locality now simply reads that region back off
302	     * the identity. Returns {@code UNKNOWN} until a customer code is assigned.
303	     */
304	    @Transient
305	    public String getLocality() {
306	        if (this.customerCode == null) {
307	            return "UNKNOWN";
308	        }
309	        int dash = this.customerCode.indexOf('-');
310	        return dash < 0 ? this.customerCode : this.customerCode.substring(0, dash);
311	    }
312	
313	    /** Region whose postcode range contains the given postcode, or {@code null} when none does. */
314	    private static String regionForPostcode(String postcode) {
315	        if (postcode == null) {
316	            return null;
317	        }
318	        int value;
319	        try {
320	            value = Integer.parseInt(postcode.trim());
321	        }
322	        catch (NumberFormatException ex) {
323	            return null;
324	        }
325	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
326	            int[] range = entry.getValue();
327	            if (value >= range[0] && value <= range[1]) {
328	                return entry.getKey();
329	            }
330	        }
331	        return null;
332	    }
333	
334	    /**
335	     * The owner's identity key, the single derived value all duplicate detection is based on. It is
336	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone
337	     * is the stored E.164 value, the email is the stored lower-cased value (empty when absent) and
338	     * the household segment is the deterministic {@code householdId} derived from the last name and
339	     * postcode (empty only when no household id has been assigned). Two owners are duplicates only
340	     * when their whole identity keys are equal.
341	     */
342	    @Transient
343	    public String getIdentityKey() {
344	        String telephonePart = this.telephone == null ? "" : this.telephone;
345	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
346	        String householdPart = this.householdId == null ? "" : this.householdId;
347	        return telephonePart + "|" + emailPart + "|" + householdPart;
348	    }
349	
350	    public String getHouseholdId() {
351	        return this.householdId;
352	    }
353	
354	    public void setHouseholdId(String householdId) {
355	        this.householdId = householdId;
356	    }
357	
358	    public Integer getNamesakeCount() {
359	        return this.namesakeCount;
360	    }
361	
362	    public void setNamesakeCount(Integer namesakeCount) {
363	        this.namesakeCount = namesakeCount;
364	    }
365	
366	    public Integer getHouseholdSize() {
367	        return this.householdSize;
368	    }
369	
370	    public void setHouseholdSize(Integer householdSize) {
371	        this.householdSize = householdSize;
372	    }
373	
374	    public String getPostcode() {
375	        return this.postcode;
376	    }
377	
378	    public void setPostcode(String postcode) {
379	        this.postcode = postcode;
380	    }
381	
382	    public Boolean getPossibleDuplicate() {
383	        return this.possibleDuplicate;
384	    }
385	
386	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
387	        this.possibleDuplicate = possibleDuplicate;
388	    }
389	
390	    public Integer getPossibleDuplicateOf() {
391	        return this.possibleDuplicateOf;
392	    }
393	
394	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
395	        this.possibleDuplicateOf = possibleDuplicateOf;
396	    }
397	
398	    protected Set<Pet> getPetsInternal() {
399	        if (this.pets == null) {
400	            this.pets = new HashSet<>();
401	        }
402	        return this.pets;
403	    }
404	
405	    protected void setPetsInternal(Set<Pet> pets) {
406	        this.pets = pets;
407	    }
408	
409	    public List<Pet> getPets() {
410	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
411	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
412	        return Collections.unmodifiableList(sortedPets);
413	    }
414	
415	    public void setPets(List<Pet> pets) {
416	        this.pets = new HashSet<>(pets);
417	    }
418	
419	    public void addPet(Pet pet) {
420	        getPetsInternal().add(pet);
421	        pet.setOwner(this);
422	    }
423	
424	    /**
425	     * Return the Pet with the given name, or null if none found for this Owner.
426	     *
427	     * @param name to test
428	     * @return true if pet name is already in use
429	     */
430	    public Pet getPet(String name) {
431	        return getPet(name, false);
432	    }
433	
434	    /**
435	     * Return the Pet with the given name, or null if none found for this Owner.
436	     *
437	     * @param name to test
438	     * @return true if pet name is already in use
439	     */
440	    public Pet getPet(String name, boolean ignoreNew) {
441	        name = name.toLowerCase();
442	        for (Pet pet : getPetsInternal()) {
443	            if (!ignoreNew || !pet.isNew()) {
444	                String compName = pet.getName();
445	                compName = compName.toLowerCase();
446	                if (compName.equals(name)) {
447	                    return pet;
448	                }
449	            }
450	        }
451	        return null;
452	    }
453	
454	    public Pet getPet(Integer petId) {
455	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
456	    }
457	
458	    @Override
459	    public String toString() {
460	        return new ToStringCreator(this)
461	
462	            .append("id", this.getId())
463	            .append("new", this.isNew())
464	            .append("lastName", this.getLastName())
465	            .append("firstName", this.getFirstName())
466	            .append("address", this.address)
467	            .append("city", this.city)
468	            .append("telephone", this.telephone)
469	            .append("email", this.email)
470	            .toString();
471	    }
472	}
