88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        boolean bulkSignupWarning = isBulkSignupWarning();
101	        List<OwnerDto> ownerDtos = ownerMapper.toOwnerDtoCollection(owners);
102	        ownerDtos.forEach(ownerDto -> ownerDto.setBulkSignupWarning(bulkSignupWarning));
103	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
104	    }
105	
106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
114	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
115	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
121	        String address = normalizeAddress(ownerFieldsDto.getAddress());
122	        List<String> missingFields = new ArrayList<>();
123	        if (isBlank(ownerFieldsDto.getFirstName())) {
124	            missingFields.add("firstName");
125	        }
126	        if (isBlank(ownerFieldsDto.getLastName())) {
127	            missingFields.add("lastName");
128	        }
129	        if (isBlank(address)) {
130	            missingFields.add("address");
131	        }
132	        if (isBlank(ownerFieldsDto.getCity())) {
133	            missingFields.add("city");
134	        }
135	        if (isBlank(ownerFieldsDto.getTelephone())) {
136	            missingFields.add("telephone");
137	        }
138	        if (!missingFields.isEmpty()) {
139	            throw new MissingOwnerFieldsException(missingFields);
140	        }
141	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
142	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
143	        HttpHeaders headers = new HttpHeaders();
144	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
145	        owner.setAddress(address);
146	        owner.setTelephone(telephone);
147	        validatePostcode(owner.getPostcode(), owner.getRegion());
148	        // The household is keyed deterministically on (lastName, postcode): every owner receives the
149	        // same stable householdId as anyone sharing its normalized last name and postcode, without any
150	        // explicit link. This computed value drives duplicate detection and the household size.
151	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
152	        // A second owner joining an existing household (same computed householdId) is rejected as a
153	        // household duplicate. Declaring 'sharesHousehold' only bypasses this block — it no longer
154	        // creates the link, since the link is now implicit in the computed householdId.
155	        if (!sharesHousehold && isHouseholdInUse(owner)) {
156	            throw new DuplicateIdentityException(owner.getIdentityKey());
157	        }
158	        // Remaining duplicate detection is consolidated into the single derived identity key: a create
159	        // is rejected when the new owner's whole identity key equals an existing owner's.
160	        if (isIdentityKeyInUse(owner.getIdentityKey())) {
161	            throw new DuplicateIdentityException(owner.getIdentityKey());
162	        }
163	        if (isCityAtCapacity(owner.getCity())) {
164	            throw new CityAtCapacityException(owner.getCity());
165	        }
166	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
167	            throw new FutureRegistrationDateException(owner.getRegistrationDate());
168	        }
169	        LocalDate effectiveDate = owner.getRegistrationDate() != null
170	            ? owner.getRegistrationDate() : LocalDate.now();
171	        LocalDate registrationDate = toBusinessDay(effectiveDate);
172	        if (isDailyRegistrationLimitReached(registrationDate)) {
173	            throw new DailyRegistrationLimitException(registrationDate);
174	        }
175	        owner.setRegistrationDate(registrationDate);
176	        owner.setCustomerCode(customerCodeFor(owner));
177	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
178	        owner.setHouseholdSize(householdSizeAfterCreate(owner.getHouseholdId()));
179	        // A declared household member (one that set 'sharesHousehold' to join an existing household) is
180	        // not a suspected duplicate; otherwise fall back to the soft last-name + postcode match.
181	        Integer possibleDuplicateOf = sharesHousehold ? null : possibleDuplicateOf(owner);
182	        owner.setPossibleDuplicate(possibleDuplicateOf != null);
183	        owner.setPossibleDuplicateOf(possibleDuplicateOf);
184	        this.clinicService.saveOwner(owner);
185	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
186	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
187	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
188	        ownerDto.setBulkSignupWarning(isBulkSignupWarning());
189	        headers.setLocation(UriComponentsBuilder.newInstance()
190	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
191	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
192	    }
