275	
276	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
277	    @Override
278	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
279	        Owner owner = this.clinicService.findOwnerById(ownerId);
280	        if (owner != null) {
281	            Pet pet = owner.getPet(petId);
282	            if (pet != null) {
283	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
284	            }
285	        }
286	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
287	    }
288	
289	    private static boolean isBlank(String value) {
290	        return value == null || value.isBlank();
291	    }
292	
293	    /**
294	     * The fixed, region-keyed inclusive 4-digit postcode ranges. A region absent from this table
295	     * (locality {@code UNKNOWN}) imposes no range, so any 4-digit postcode is accepted there.
296	     */
297	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
298	        "NSW", new int[] {2000, 2099},
299	        "VIC", new int[] {3000, 3099},
300	        "QLD", new int[] {4000, 4099});
301	
302	    /**
303	     * Validates a supplied {@code postcode} against the owner's city region. Postcode is optional:
304	     * a {@code null} or blank value is accepted (validation only applies WHEN PRESENT). When
305	     * present, the value has already passed the 4-digit format check (Bean Validation on the
306	     * request body); this enforces that it falls within the inclusive range for the city's region
307	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region imposes no range.
308	     *
309	     * @param postcode the supplied postcode (may be {@code null})
310	     * @param region the owner's locality/region derived from its city
311	     * @throws InvalidPostcodeException if the postcode is out of range for the region
312	     */
313	    private static void validatePostcode(String postcode, String region) {
314	        if (isBlank(postcode)) {
315	            return;
316	        }
317	        int[] range = REGION_POSTCODES.get(region);
318	        if (range == null) {
319	            return;
320	        }
321	        int value;
322	        try {
323	            value = Integer.parseInt(postcode);
324	        }
325	        catch (NumberFormatException e) {
326	            throw new InvalidPostcodeException(postcode);
327	        }
328	        if (value < range[0] || value > range[1]) {
329	            throw new InvalidPostcodeException(postcode);
330	        }
331	    }
332	
333	    /**
334	     * Normalizes a street address into the canonical form stored on and returned for a newly
335	     * created owner. A {@code null} value becomes the empty string; otherwise surrounding
336	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space, the
337	     * text is upper-cased, and common street-type abbreviations are expanded on a whole-word
338	     * basis ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The normalized
339	     * value is what gets persisted, echoed back, and used for every address comparison (household
340	     * duplicate detection and the shared household identifier).
341	     *
342	     * @param rawAddress the address value as supplied by the client
343	     * @return the normalized address (possibly empty, never {@code null})
344	     */
345	    private static String normalizeAddress(String rawAddress) {
346	        if (rawAddress == null) {
347	            return "";
348	        }
349	        String collapsed = rawAddress.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
350	        if (collapsed.isEmpty()) {
351	            return "";
352	        }
353	        String[] tokens = collapsed.split(" ");
354	        StringBuilder sb = new StringBuilder(collapsed.length());
355	        for (int i = 0; i < tokens.length; i++) {
356	            String token = tokens[i];
357	            switch (token) {
358	                case "ST" -> token = "STREET";
359	                case "RD" -> token = "ROAD";
360	                case "AVE" -> token = "AVENUE";
361	                default -> { }
362	            }
363	            if (i > 0) {
364	                sb.append(' ');
365	            }
366	            sb.append(token);
367	        }
368	        return sb.toString();
369	    }
370	
371	    /**
372	     * Builds the customer code assigned to a newly created owner. The code is formatted
373	     * {@code <REGION>-<HASH8>} where {@code REGION} is the region derived from the owner's postcode
374	     * (see {@link Owner#getRegion()}) and {@code HASH8} is the first 8 upper-case hex characters of
375	     * the SHA-256 digest of the owner's normalized (E.164) telephone concatenated with its last
376	     * name (e.g. {@code NSW-1A2B3C4D}). No sequence number is involved, so the code depends only on
377	     * the owner's own region and identity.
378	     *
379	     * @param owner the owner being created, with telephone already normalized and postcode/city set
380	     * @return the customer code to assign
381	     */
382	    private static String customerCodeFor(Owner owner) {
383	        return owner.getRegion() + "-" + telephoneNameHash(owner.getTelephone(), owner.getLastName());
384	    }
385	
386	    /**
387	     * Computes the {@code HASH8} segment of the customer code: the first 8 upper-case hex
388	     * characters of the SHA-256 digest of the normalized (E.164) telephone concatenated with the
389	     * last name.
390	     *
391	     * @param normalizedTelephone the owner's telephone in E.164 form
392	     * @param lastName the owner's last name
393	     * @return the 8-character upper-case hex hash
394	     */
395	    private static String telephoneNameHash(String normalizedTelephone, String lastName) {
396	        String key = (normalizedTelephone == null ? "" : normalizedTelephone)
397	            + (lastName == null ? "" : lastName);
398	        try {
399	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
400	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
401	            StringBuilder sb = new StringBuilder(digest.length * 2);
402	            for (byte b : digest) {
403	                sb.append(String.format("%02x", b));
404	            }
405	            return sb.substring(0, 8).toUpperCase(java.util.Locale.ROOT);
406	        }
407	        catch (java.security.NoSuchAlgorithmException e) {
408	            throw new IllegalStateException("SHA-256 not available", e);
409	        }
410	    }
411	
412	    /**
413	     * Normalizes a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value
414	     * already carrying a leading {@code '+'} keeps its country code; otherwise country code
415	     * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
416	     * The result must carry a leading {@code '+'} followed by 8 to 15 digits, and the length of
417	     * the national number must match the country code: {@code +61} requires 9 national digits and
418	     * {@code +1} requires 10.
419	     *
420	     * @param rawTelephone the telephone value as supplied by the client
421	     * @return the telephone in E.164 form (e.g. {@code +61412345678})
422	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
423	     */
424	    private static String normalizeTelephone(String rawTelephone) {
425	        if (rawTelephone == null) {
426	            throw new InvalidTelephoneException(rawTelephone);
427	        }
428	        String cleaned = rawTelephone.replaceAll("[\\s\\-()]", "");
429	        String e164;
430	        if (cleaned.startsWith("+")) {
431	            String digits = cleaned.substring(1);
432	            if (!digits.matches("[0-9]+")) {
433	                throw new InvalidTelephoneException(rawTelephone);
434	            }
435	            e164 = "+" + digits;
436	        } else {
437	            if (!cleaned.matches("[0-9]+")) {
438	                throw new InvalidTelephoneException(rawTelephone);
439	            }
440	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
441	            e164 = "+61" + national;
442	        }
443	        int digitCount = e164.length() - 1;
444	        if (digitCount < 8 || digitCount > 15) {
445	            throw new InvalidTelephoneException(rawTelephone);
446	        }
447	        if (e164.startsWith("+61")) {
448	            if (e164.length() - "+61".length() != 9) {
449	                throw new InvalidTelephoneException(rawTelephone);
450	            }
451	        }
452	        else if (e164.startsWith("+1")) {
453	            if (e164.length() - "+1".length() != 10) {
454	                throw new InvalidTelephoneException(rawTelephone);
455	            }
456	        }
457	        return e164;
458	    }
459	
460	    /**
461	     * Determines whether any existing owner already carries the given identity key. The identity key
462	     * ({@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}) is the single value
463	     * all duplicate detection is based on, so two owners collide only when their whole identity keys
464	     * are equal.
465	     *
466	     * @param identityKey the identity key of the owner being created
467	     * @return {@code true} if another owner already has the same identity key
468	     */
469	    private boolean isIdentityKeyInUse(String identityKey) {
470	        return this.clinicService.findAllOwners().stream()
471	            .map(Owner::getIdentityKey)
472	            .anyMatch(identityKey::equals);
473	    }
474	
475	    /**
476	     * Finds an existing owner that the owner being created is a possible (soft) duplicate of: one
477	     * that shares the same last name (compared case-insensitively, whitespace-collapsed) and the
478	     * same postcode but carries a <em>different</em> telephone. Such a create is not rejected as a
479	     * hard duplicate, but is flagged. An owner with no postcode can never be a soft duplicate. When
480	     * several owners match, the earliest (lowest id) is returned so the result is deterministic.
481	     *
482	     * @param owner the owner being created (telephone already normalized, postcode set)
483	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
484	     */
485	    private Integer possibleDuplicateOf(Owner owner) {
486	        if (isBlank(owner.getPostcode())) {
487	            return null;
488	        }
489	        String normalizedLastName = normalizeIdentity(owner.getLastName());
490	        return this.clinicService.findAllOwners().stream()
491	            .filter(existing -> existing.getId() != null
492	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName)
493	                && owner.getPostcode().equals(existing.getPostcode())
494	                && !java.util.Objects.equals(owner.getTelephone(), existing.getTelephone()))
495	            .map(Owner::getId)
496	            .min(Integer::compareTo)
497	            .orElse(null);
498	    }
499	
500	    /**
501	     * Counts how many existing owners already share the given first name and last name with the
502	     * owner being created. Both names are compared case-insensitively (after trimming and
503	     * collapsing runs of whitespace). The count reflects the state before the new owner is
504	     * persisted, so a first, otherwise-unique owner yields {@code 0}.
505	     *
506	     * @param firstName the first name of the owner being created
507	     * @param lastName the last name of the owner being created
508	     * @return the number of existing owners sharing the same first and last name
509	     */
510	    private int namesakeCount(String firstName, String lastName) {
511	        String normalizedFirstName = normalizeIdentity(firstName);
512	        String normalizedLastName = normalizeIdentity(lastName);
513	        return (int) this.clinicService.findAllOwners().stream()
514	            .filter(existing -> normalizeIdentity(existing.getFirstName()).equals(normalizedFirstName)
515	                && normalizeIdentity(existing.getLastName()).equals(normalizedLastName))
516	            .count();
517	    }
518	
519	    /**
520	     * Counts how many members the owner being created belongs to in its household, including
521	     * itself, as of this create. Members are the owners sharing the given {@code householdId};
522	     * the new owner is not yet persisted, so its own membership is added to the existing count.
523	     * An owner not assigned to a shared household ({@code householdId} is {@code null}) is a
524	     * household of one.
525	     *
526	     * @param householdId the shared household identifier assigned to the owner being created, or
527	     *                    {@code null} if the owner does not share a household
528	     * @return the number of household members after this create (at least 1)
529	     */
530	    private int householdSizeAfterCreate(String householdId) {
531	        if (householdId == null) {
532	            return 1;
533	        }
534	        long existing = this.clinicService.findAllOwners().stream()
535	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
536	            .count();
537	        return (int) existing + 1;
538	    }
539	
540	    /**
541	     * The maximum number of owners permitted in a single city. Once a city already contains this
542	     * many owners it is considered full and no further owners may be created there.
543	     */
544	    private static final int CITY_CAPACITY = 50;
545	
546	    /**
547	     * Determines whether the given city has already reached its capacity, i.e. already contains
548	     * {@value #CITY_CAPACITY} or more existing owners. Cities are compared case-insensitively after
549	     * collapsing runs of whitespace to a single space and trimming.
550	     *
551	     * @param city the city of the owner being created
552	     * @return {@code true} if the city already contains {@value #CITY_CAPACITY} or more owners
553	     */
554	    private boolean isCityAtCapacity(String city) {
555	        String normalizedCity = normalizeIdentity(city);
556	        long count = this.clinicService.findAllOwners().stream()
557	            .filter(existing -> normalizeIdentity(existing.getCity()).equals(normalizedCity))
558	            .count();
559	        return count >= CITY_CAPACITY;
560	    }
561	
562	    /**
563	     * The maximum number of owners that may be created on any single day. Once this many owners
564	     * already carry a {@code registrationDate} of the current day, no further owners may be created
565	     * that day.
566	     */
567	    private static final int DAILY_REGISTRATION_LIMIT = 100;
568	
569	    /**
570	     * Determines whether the daily registration limit has already been reached, i.e. whether
571	     * {@value #DAILY_REGISTRATION_LIMIT} or more existing owners already carry the given date as
572	     * their {@code registrationDate}.
573	     *
574	     * @param date the current day
575	     * @return {@code true} if {@value #DAILY_REGISTRATION_LIMIT} or more owners were already
576	     *         registered on the given date
577	     */
578	    /**
579	     * Rolls a registration date forward onto a business day. A date that already falls on a
580	     * weekday is returned unchanged; a Saturday or Sunday is rolled forward to the following
581	     * Monday. This adjusted date is what gets stored as the {@code registrationDate} and drives
582	     * everything derived from it (the membership number's year segment, the daily create-limit).
583	     *
584	     * @param date the effective registration date (supplied by the client or defaulted to the
585	     *             server's current date)
586	     * @return the same date if it is a weekday, otherwise the following Monday
587	     */
588	    private static LocalDate toBusinessDay(LocalDate date) {
589	        DayOfWeek dayOfWeek = date.getDayOfWeek();
590	        if (dayOfWeek == DayOfWeek.SATURDAY) {
591	            return date.plusDays(2);
592	        }
593	        if (dayOfWeek == DayOfWeek.SUNDAY) {
594	            return date.plusDays(1);
595	        }
596	        return date;
597	    }
598	
599	    private boolean isDailyRegistrationLimitReached(LocalDate date) {
600	        long count = this.clinicService.findAllOwners().stream()
601	            .filter(existing -> date.equals(existing.getRegistrationDate()))
602	            .count();
603	        return count >= DAILY_REGISTRATION_LIMIT;
604	    }
605	
606	    /**
607	     * The number of owners that may be created on a single day before the bulk-signup warning is
608	     * raised. Once <em>more than</em> this many owners already carry the current business day as
609	     * their {@code registrationDate}, responses flag {@code bulkSignupWarning} true.
610	     */
611	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
612	
613	    /**
614	     * Determines whether more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been
615	     * created today, i.e. already carry the current business day as their {@code registrationDate}.
616	     * This shares the daily create-limit's accumulation path (owners counted by registration date).
617	     *
618	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners are already
619	     *         registered on today's business day
620	     */
621	    private boolean isBulkSignupWarning() {
622	        LocalDate today = toBusinessDay(LocalDate.now());
623	        long count = this.clinicService.findAllOwners().stream()
624	            .filter(existing -> today.equals(existing.getRegistrationDate()))
625	            .count();
626	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
627	    }
628	
629	    /**
630	     * Determines whether the owner being created joins an existing household, i.e. some other owner
631	     * already carries the same computed {@code householdId} (equivalently, shares its normalized last
632	     * name and postcode). An owner with no postcode is never treated as joining a household, mirroring
633	     * the soft-duplicate rule that an owner with no postcode can never match one.
634	     *
635	     * @param owner the owner being created, with {@code householdId} already computed
636	     * @return {@code true} if another owner already belongs to the same household
637	     */
638	    private boolean isHouseholdInUse(Owner owner) {
639	        if (isBlank(owner.getPostcode())) {
640	            return false;
641	        }
642	        String householdId = owner.getHouseholdId();
643	        return this.clinicService.findAllOwners().stream()
644	            .anyMatch(existing -> existing.getId() != null
645	                && householdId.equals(existing.getHouseholdId()));
646	    }
647	
648	    /**
649	     * Derives the stable household identifier for a given last name and postcode. The value is the
650	     * first 12 upper-case hex characters of the SHA-256 digest of {@code normalizedLastName + '|' +
651	     * postcode}, so it is deterministic across calls and identical for every owner sharing the same
652	     * normalized last name and postcode — they belong to the same household automatically.
653	     *
654	     * @param lastName the last name of the household
655	     * @param postcode the postcode of the household (may be {@code null})
656	     * @return the deterministic household identifier
657	     */
658	    private static String householdIdFor(String lastName, String postcode) {
659	        String key = normalizeIdentity(lastName) + "|" + (postcode == null ? "" : postcode);
660	        try {
661	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
662	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
663	            StringBuilder sb = new StringBuilder(digest.length * 2);
664	            for (byte b : digest) {
665	                sb.append(String.format("%02x", b));
666	            }
667	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
668	        }
669	        catch (java.security.NoSuchAlgorithmException e) {
670	            throw new IllegalStateException("SHA-256 not available", e);
671	        }
672	    }
673	
674	    /**
675	     * Normalizes a text field for household-identity comparison: {@code null} becomes the empty
676	     * string, surrounding whitespace is trimmed, internal runs of whitespace are collapsed to a
677	     * single space, and the result is lower-cased.
678	     *
679	     * @param value the raw field value
680	     * @return the normalized value used for case-insensitive, whitespace-insensitive comparison
681	     */
682	    private static String normalizeIdentity(String value) {
683	        if (value == null) {
684	            return "";
685	        }
686	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
687	    }
688	}
