 * disposable-domain blocklist (mailinator.com, tempmail.com, guerrillamail.com). Carries the
 * offending value so the exception handler can report it.
 */
public class DisposableEmailDomainException extends RuntimeException {

    private final String rejectedValue;

    public DisposableEmailDomainException(String rejectedValue) {
        super("Email domain is on the disposable-domain blocklist");
        this.rejectedValue = rejectedValue;
